import { z } from "zod"
import { BOSS_BASE_LIMITS, BOSS_LIMITS } from "./boss-words"

/**
 * What a boss gains only when its document says so: the most life one blow takes (`damage_cap`), the most it loses over a few seconds (`dps_cap`), its life coming back once it
 * has been left alone a while (`regen`), and more life and damage for each more player near (`scaling`). Its going home is the leash (`boss.leash`).
 * The four are fields of `BossSchema`, all optional: a boss without them is generated byte for byte as before (`fabric/boss-base.ts` writes the Java).
 * No Node APIs: the app's window reads it too.
 */

const L = BOSS_BASE_LIMITS
const number = (range: { min: number; max: number }) => z.number().finite().min(range.min).max(range.max)

export const BossDpsCapSchema = z.strictObject({ amount: number(L.dps.amount), seconds: number(L.dps.seconds) })
export const BossRegenSchema = z.strictObject({ per_second: number(L.regen.per_second), after_seconds_without_damage: number(L.regen.after), in_fight: z.boolean() })
export const BossScalingSchema = z.strictObject({
  per_extra_player: z.strictObject({ health: number(L.scaling.health), damage: number(L.scaling.damage) }),
  radius: number(L.scaling.radius),
  max_players: z.number().int().min(L.scaling.players.min).max(L.scaling.players.max),
})

/** The four fields as `BossSchema` spreads them; null or absent: none of it, as it always was. */
export const BossBaseShape = {
  /** The most life one blow takes from it (a blow that would take more takes this much). The void and /kill are not held to it. */
  damage_cap: number(L.cap).nullable().optional(),
  /** The most life it loses in any `seconds` seconds; once it has lost that much, blows take nothing until the oldest falls out of the window. */
  dps_cap: BossDpsCapSchema.nullable().optional(),
  /** Life a second it gets back once it has lost none for `after_seconds_without_damage`; with `in_fight` false only while it has nobody to fight. Never past its most, never back a phase. */
  regen: BossRegenSchema.nullable().optional(),
  /** Per player more than one within `radius` blocks (counting up to `max_players`): its most life × (1 + health) and its damage × (1 + damage) each. */
  scaling: BossScalingSchema.nullable().optional(),
} as const

export type BossBase = { damage_cap?: number | null; dps_cap?: z.infer<typeof BossDpsCapSchema> | null; regen?: z.infer<typeof BossRegenSchema> | null; scaling?: z.infer<typeof BossScalingSchema> | null }

/** Whether a boss has any of the four: only then is any of their Java written. */
export const hasBossBase = (boss: BossBase | null | undefined) => Boolean(boss && (boss.damage_cap || boss.dps_cap || boss.regen || boss.scaling))

const num = (value: number, digits = 2) => Number(value.toFixed(digits))
const percent = (share: number) => `${num(share * 100, 1)}%`

/**
 * What of the four cannot be played as written, in plain words, against the creature's own life (`health`):
 * - a cap of one blow as big as its whole life is no cap;
 * - a cap over a few seconds smaller than the cap of one blow makes the one-blow cap mean nothing (the window holds it first);
 * - life coming back while it is being hit, as fast as the window lets it lose, would make it impossible to kill.
 */
export function bossBaseIssues(boss: BossBase, health: number) {
  const found: { path: (string | number)[]; message: string }[] = []
  if (boss.damage_cap && boss.damage_cap >= health)
    found.push({ path: ["boss", "damage_cap"], message: `单次最多掉的血（damage_cap ${num(boss.damage_cap)}）不比它的满血（${num(health)}）少，等于没写：一般写满血的 4%–6%（这只大约 ${num(health * 0.04, 0)}–${num(health * 0.06, 0)}）；不想限制就不写` })
  if (boss.damage_cap && boss.dps_cap && boss.dps_cap.amount < boss.damage_cap)
    found.push({ path: ["boss", "dps_cap", "amount"], message: `每 ${num(boss.dps_cap.seconds)} 秒最多掉的血（dps_cap.amount ${num(boss.dps_cap.amount)}）比单次最多掉的血（damage_cap ${num(boss.damage_cap)}）还少，单次上限就没用了：amount 至少写到 damage_cap 那么多，一般是它的 2–4 倍` })
  if (boss.regen?.in_fight && boss.regen.after_seconds_without_damage === 0 && boss.dps_cap && boss.regen.per_second * boss.dps_cap.seconds >= boss.dps_cap.amount)
    found.push({ path: ["boss", "regen", "per_second"], message: `战斗里也回血（regen.in_fight）、挨打也不停（after_seconds_without_damage 是 0），每秒回 ${num(boss.regen.per_second)} 血，可是每 ${num(boss.dps_cap.seconds)} 秒最多只掉 ${num(boss.dps_cap.amount)} 血：回得比能打掉的还快，它永远打不死。把 after_seconds_without_damage 写成几秒，或者把回血写慢` })
  return found
}

/**
 * 「单次最多掉 40 血，每 5 秒最多掉 120 血（就算一直打，满血 600 也要 25 秒以上）；10 秒没掉血、身边没有要打的人时，每秒回 3 血；32 格内每多一个玩家（最多算 4 个），
 * 满血多 50%、伤害多 20%」. `health`: its own life, where known, for how long it takes at the least and where the game's ceiling stops the scaling. Empty without any of the four.
 */
export function bossBaseWords(boss: BossBase, health?: number) {
  const parts: string[] = []
  if (boss.damage_cap) parts.push(`单次最多掉 ${num(boss.damage_cap)} 血（多大的伤害都只掉这么多，掉进虚空和 /kill 不算）`)
  if (boss.dps_cap) {
    const least = health ? (health / boss.dps_cap.amount) * boss.dps_cap.seconds : null
    parts.push(`每 ${num(boss.dps_cap.seconds)} 秒最多掉 ${num(boss.dps_cap.amount)} 血（掉够了，这段时间里再打也不掉${least ? `；就算一直打，满血 ${num(health!)} 也要 ${num(least, 0)} 秒以上` : ""}）`)
  }
  if (boss.regen)
    parts.push(`${boss.regen.after_seconds_without_damage ? `${num(boss.regen.after_seconds_without_damage)} 秒没掉血` : "不管挨不挨打"}${boss.regen.in_fight ? "" : "、身边没有要打的人"}时，每秒回 ${num(boss.regen.per_second)} 血（回不过满血，也不会回到上一个阶段）`)
  if (boss.scaling) {
    const { health: more, damage } = boss.scaling.per_extra_player
    const most = health ? health * (1 + more * (boss.scaling.max_players - 1)) : null
    parts.push(
      `${num(boss.scaling.radius)} 格内每多一个玩家（最多算 ${boss.scaling.max_players} 个）${[more ? `满血多 ${percent(more)}` : "", damage ? `伤害多 ${percent(damage)}` : ""].filter(Boolean).join("、") || "什么也不变"}${
        most && more ? `（满血最多 ${num(Math.min(most, L.most))}${most > L.most ? `，游戏的上限是 ${L.most}` : ""}）` : ""
      }，人走了再降回来，血量按比例跟着变，血条和阶段线不乱`,
    )
  }
  return parts.join("；")
}

/** What an AI is told of the four, in the Boss guide (`BOSS_INSTRUCTIONS`), with the numbers an epic boss starts from. */
export const BOSS_BASE_INSTRUCTIONS =
  ` 下面四项适合需要控制爆发伤害、回血或多人难度的 Boss，都可以不写（不写就和以前一样）；人要的是一场史诗 Boss 战、或者说了“不能被秒”“别让人一下打死”“多人更难”，就都写上：` +
  ` damage_cap（${L.cap.min}–${L.cap.max}）：一下最多掉多少血，再大的伤害也只掉这么多（掉进虚空、/kill 不受限）；一般写满血的 4%–6%（满血 600 写 25–35），不能比满血多。` +
  ` dps_cap：{amount ${L.dps.amount.min}–${L.dps.amount.max}, seconds ${L.dps.seconds.min}–${L.dps.seconds.max}}——任意 seconds 秒里最多掉 amount 血，掉够了这段时间里再打也不掉，什么高伤害打法都融不掉它；一般 seconds 写 5，amount 写满血的 12%–20%（满血 600 写 80–120，单人最快也要半分钟左右），amount 不能比 damage_cap 小。` +
  ` regen：{per_second ${L.regen.per_second.min}–${L.regen.per_second.max}, after_seconds_without_damage ${L.regen.after.min}–${L.regen.after.max}, in_fight}——after_seconds_without_damage 秒没掉血以后每秒回 per_second 血；in_fight 为 false 时只在身边没有要打的人时回（脱战回血），true 时打着打着停手也会回；回不过满血，也不会回到上一个阶段。一般 per_second 写满血的 0.5%–1%，after_seconds_without_damage 写 8–15，in_fight 写 false。` +
  ` scaling：{per_extra_player: {health ${L.scaling.health.min}–${L.scaling.health.max}, damage ${L.scaling.damage.min}–${L.scaling.damage.max}}, radius ${L.scaling.radius.min}–${L.scaling.radius.max}, max_players ${L.scaling.players.min}–${L.scaling.players.max}}——radius 格内（观战的不算）每多一个玩家，满血多 health 倍、伤害多 damage 倍（0.5 就是多一半），最多算 max_players 个人；每半秒数一次，人走了降回来，血量按比例跟着变（血条、阶段线都对）；满血到不了 ${L.most}（游戏的上限）以上。一般 health 0.5、damage 0.15–0.25、radius 32（和离开重置的 ${BOSS_LIMITS.battle} 格一样）、max_players 4。` +
  ` 例（满血 600 的史诗 Boss）：{"damage_cap":30,"dps_cap":{"amount":100,"seconds":5},"regen":{"per_second":4,"after_seconds_without_damage":10,"in_fight":false},"scaling":{"per_extra_player":{"health":0.5,"damage":0.2},"radius":32,"max_players":4}}。`
